<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { ElMessageBox } from 'element-plus'
import jsQR from 'jsqr'
import { createStockClient } from './stock-api.mjs'

const api=createStockClient()
const kind=ref('inbound'),items=ref([]),draft=ref(null),usingDraft=ref(false),revision=ref('0')
const busy=ref(false),loading=ref(true),error=ref(''),notice=ref(''),pending=ref(null),result=ref(null)
const token=ref(''),scanInput=ref(null),scanCount=ref(0),query=ref(''),searched=ref(''),matches=ref([]),cursor=ref(null),searching=ref(false)
const obsolete=ref(false),notFound=ref(false),video=ref(null),camera=ref(false),storageFailed=ref(false)
const controller=new AbortController()
let searchRequest,owner,disposed=false,epoch=0,cameraEpoch=0,queue=Promise.resolve(),stream,frame,openingCamera=false
const total=computed(()=>items.value.reduce((sum,row)=>sum+BigInt(row.quantity),0n).toString())
const mode=computed(()=>pending.value?.kind || kind.value)
const cartKey=list=>JSON.stringify(list.map(({productId,quantity})=>({productId,quantity})).sort((a,b)=>a.productId.localeCompare(b.productId)))
const dirty=computed(()=>items.value.length>0 && !(usingDraft.value&&draft.value?.kind===kind.value&&cartKey(items.value)===cartKey(draft.value.items)))
const messages={LOGIN_REQUIRED:'Please sign in again. Pending transactions are retained for verification.',ADMIN_REQUIRED:'An Administrator account is required.',INVALID_QR:'This is not a product QR. Rescan or search for the product.',PRODUCT_NOT_FOUND_OR_DELETED:'A product is missing or was deleted. Refresh the list.',STOCK_VERSION_CONFLICT:'Stock changed on another device. Submit again to review the latest quantities.',DRAFT_VERSION_CONFLICT:'The saved draft changed on another device. Refresh the draft before saving or submitting.',WAREHOUSE_RESTORED:'The warehouse was restored after this request was prepared. Verify its result before discarding the obsolete request.',MAINTENANCE:'Warehouse operations are paused for maintenance.',ADMIN_BACKUP_REQUIRED:'Complete a successful backup before continuing.',QUANTITY_OVERFLOW:'The resulting quantity is outside the supported range.',INVALID_ITEMS:'Use at most 1,000 different products in one transaction.',LOCAL_STORAGE_FAILURE:'This window cannot retain a pending transaction safely. Close and reopen the app before submitting.'}
function report(failure){error.value=messages[failure.code]||messages[failure.message]||'The result could not be confirmed. Verify any pending request before trying again.'}
const key=()=> 'warehouse-pending:'+owner
function store(value){try{if(value)sessionStorage.setItem(key(),JSON.stringify(value));else sessionStorage.removeItem(key())}catch{storageFailed.value=true;const failure=Error('LOCAL_STORAGE_FAILURE');failure.code='LOCAL_STORAGE_FAILURE';throw failure}pending.value=value}
function stopCamera(){cameraEpoch++;if(frame)cancelAnimationFrame(frame);stream?.getTracks().forEach(track=>track.stop());stream=null;camera.value=false}
function clearCart(){epoch++;items.value=[];usingDraft.value=false;stopCamera()}
function interrupt(failure){clearCart();report(failure);notice.value='Connection interrupted. Unsaved items were cleared; saved drafts and pending requests are retained.'}
async function refreshDraft(){const response=await api.draft(controller.signal);if(!disposed){draft.value=response.draft;revision.value=response.draft?.revision||'0'}}
async function initialize(){try{const session=await api.session(controller.signal);if(disposed)return;owner=session.user.id;try{pending.value=JSON.parse(sessionStorage.getItem(key())||'null')}catch{storageFailed.value=true;error.value='This window cannot safely retain pending transactions. Close and reopen the app.'}await refreshDraft()}catch(failure){if(!disposed)report(failure)}finally{loading.value=false;nextTick(()=>scanInput.value?.focus())}}
function add(product){if(busy.value||pending.value||disposed)return;const row=items.value.find(row=>row.productId===product.id);if(row){if(!Number.isSafeInteger(row.quantity+1)){report(Error('QUANTITY_OVERFLOW'));return false}row.quantity++}else{if(items.value.length>=1000){report(Error('INVALID_ITEMS'));return false}items.value.push({productId:product.id,name:product.name,productCode:product.productCode,quantity:1})}result.value=null;return true}
function scan(){const value=token.value.trim();token.value='';if(!value||busy.value||pending.value||loading.value)return;const scope=epoch;scanCount.value++;queue=queue.then(async()=>{if(disposed||scope!==epoch)return;try{const response=await api.resolve(value,controller.signal);if(!disposed&&scope===epoch){if(add(response.product))error.value=''}}catch(failure){if(disposed||scope!==epoch)return;if(!failure.code||['MAINTENANCE','SESSION_REPLACED_OR_REVOKED','UNAUTHENTICATED'].includes(failure.code))interrupt(failure);else report(failure)}}).finally(()=>{scanCount.value--;nextTick(()=>scanInput.value?.focus())})}
function adjust(row,amount){if(busy.value||pending.value)return;if(!Number.isSafeInteger(row.quantity+amount)){report(Error('QUANTITY_OVERFLOW'));return}row.quantity+=amount;if(row.quantity<=0)items.value=items.value.filter(item=>item!==row)}
async function search(append=false){searchRequest?.abort();const request=new AbortController();searchRequest=request;searching.value=true;error.value='';if(!append)searched.value=query.value.trim();try{const response=await api.search(searched.value,append?cursor.value:null,request.signal);if(!disposed&&!request.signal.aborted){matches.value=append?[...matches.value,...response.products]:response.products;cursor.value=response.nextCursor}}catch(failure){if(!disposed&&!request.signal.aborted){if(!failure.code)interrupt(failure);else report(failure)}}finally{if(searchRequest===request)searching.value=false}}
async function saveDraft(){if(busy.value||pending.value||!items.value.length)return;if(draft.value&&!usingDraft.value){try{await ElMessageBox.confirm('Replace the saved draft with this list?','Replace saved draft',{type:'warning'})}catch{return}}if(disposed)return;busy.value=true;error.value='';try{const response=await api.saveDraft({kind:kind.value,expectedRevision:revision.value,items:items.value.map(({productId,quantity})=>({productId,quantity}))});if(disposed)return;revision.value=response.revision;usingDraft.value=true;draft.value={kind:kind.value,revision:response.revision,savedAt:response.savedAt,items:items.value.map(row=>({...row}))};notice.value='Draft saved.'}catch(failure){if(!disposed){if(!failure.code)interrupt(failure);else report(failure)}}finally{busy.value=false}}
async function loadDraft(){if(busy.value||pending.value)return;if(dirty.value&&!await confirmLeave())return;if(disposed)return;busy.value=true;try{await refreshDraft();if(disposed)return;if(draft.value){clearCart();result.value=null;kind.value=draft.value.kind;items.value=draft.value.items.map(row=>({...row}));usingDraft.value=true;notice.value='Saved draft loaded.'}}catch(failure){if(!disposed){if(!failure.code)interrupt(failure);else report(failure)}}finally{busy.value=false}}
async function reloadDraft(){if(busy.value||pending.value)return;busy.value=true;error.value='';notice.value='';try{await refreshDraft();if(!disposed){usingDraft.value=false;notice.value='Saved draft checked. Load it to replace the current list.'}}catch(failure){if(!disposed)report(failure)}finally{busy.value=false}}
async function discardDraft(){if(!draft.value||busy.value||pending.value)return;try{await ElMessageBox.confirm('Permanently discard the saved draft?','Discard draft',{type:'warning'})}catch{return}if(disposed)return;busy.value=true;try{await api.discardDraft(revision.value);if(disposed)return;if(usingDraft.value)clearCart();draft.value=null;revision.value='0';notice.value='Saved draft discarded.'}catch(failure){if(!disposed){if(!failure.code)interrupt(failure);else report(failure)}}finally{busy.value=false}}
async function send(){try{const payload=pending.value;store(payload);const response=await api.commit(payload);if(disposed)return;store(null);clearCart();kind.value=payload.kind;result.value={...response,kind:payload.kind};notice.value='Stock transaction committed.';try{await refreshDraft()}catch{if(!disposed)error.value='The stock transaction is committed, but draft status could not be refreshed. Refresh the draft before continuing.'}}catch(failure){if(disposed)return;if(['STOCK_VERSION_CONFLICT','DRAFT_VERSION_CONFLICT','PRODUCT_NOT_FOUND_OR_DELETED'].includes(failure.code)){store(null)}else{if(failure.code==='WAREHOUSE_RESTORED')obsolete.value=true;clearCart()}report(failure)}}
async function submit(){if(busy.value||scanCount.value||pending.value||!items.value.length||storageFailed.value)return;busy.value=true;error.value='';notice.value='';stopCamera();const lines=items.value.map(({productId,quantity})=>({productId,quantity}));try{const check=await api.preflight({kind:kind.value,items:lines});if(disposed)return;const negative=kind.value==='outbound'?check.items.filter(row=>row.afterQuantity<0):[];if(negative.length){try{await ElMessageBox.confirm('Insufficient stock: '+negative.map(row=>row.name+' (available '+row.quantity+', requested '+row.requested+')').join('; ')+'. Continue with negative stock?','Insufficient stock',{type:'warning'});await ElMessageBox.confirm('Confirm this stock-out transaction again.','Confirm negative stock',{type:'warning'})}catch{return}}if(disposed)return;store({requestId:crypto.randomUUID(),kind:kind.value,items:lines,expectedVersions:check.expectedVersions,restoreMarker:check.restoreMarker,...(usingDraft.value?{draftRevision:revision.value}:{})});await send()}catch(failure){if(!disposed){if(!failure.code)interrupt(failure);else report(failure)}}finally{busy.value=false}}
async function verify(){if(!pending.value||busy.value)return;busy.value=true;error.value='';try{const payload=pending.value,response=await api.status(payload.requestId);if(disposed)return;store(null);clearCart();kind.value=payload.kind;result.value={...response,kind:payload.kind};notice.value='Transaction verified as committed.';try{await refreshDraft()}catch{if(!disposed)error.value='The stock transaction is committed, but draft status could not be refreshed. Refresh the draft before continuing.'}}catch(failure){if(disposed)return;if(failure.code==='REQUEST_NOT_FOUND'){notFound.value=true;error.value='The server has not confirmed this request. Retry the original request to avoid duplicate entry.'}else report(failure)}finally{busy.value=false}}
async function retry(){if(busy.value||!pending.value||obsolete.value)return;busy.value=true;error.value='';try{await send()}finally{busy.value=false}}
async function discardObsolete(){try{await ElMessageBox.confirm('This request belongs to the warehouse before restoration and has no committed result in the current warehouse. Discard its local copy?','Discard obsolete request',{type:'warning'});await ElMessageBox.confirm('Review current stock before starting a new transaction.','Final request confirmation',{type:'warning'});if(disposed)return;store(null);clearCart();obsolete.value=false;notFound.value=false}catch{}}
async function confirmLeave(){stopCamera();try{await ElMessageBox.confirm('Unsaved items will be cleared. Leave this operation? Cancel to save a draft first.','Unsaved stock list',{type:'warning'});return true}catch{return false}}
async function leave(){if(busy.value||scanCount.value)return false;if(dirty.value&&!pending.value&&!await confirmLeave())return false;if(disposed)return false;clearCart();return true}
async function changeKind(value){if(value===kind.value||pending.value||busy.value)return;if(await leave()){kind.value=value;result.value=null;error.value='';notice.value=''}}
async function startCamera(){if(openingCamera||busy.value||pending.value)return;stopCamera();openingCamera=true;const scope=epoch,cameraScope=cameraEpoch;try{const media=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});if(disposed||scope!==epoch||cameraScope!==cameraEpoch){media.getTracks().forEach(track=>track.stop());return}stream=media;camera.value=true;await nextTick();if(disposed||scope!==epoch||cameraScope!==cameraEpoch){stopCamera();return}video.value.srcObject=media;await video.value.play();const canvas=document.createElement('canvas'),context=canvas.getContext('2d',{willReadFrequently:true});const tick=()=>{if(disposed||!stream||scope!==epoch||cameraScope!==cameraEpoch)return;const source=video.value;if(source?.readyState>=2&&source.videoWidth){const scale=Math.min(1,640/source.videoWidth);canvas.width=Math.round(source.videoWidth*scale);canvas.height=Math.round(source.videoHeight*scale);context.drawImage(source,0,0,canvas.width,canvas.height);const pixels=context.getImageData(0,0,canvas.width,canvas.height),code=jsQR(pixels.data,pixels.width,pixels.height);if(code){stopCamera();token.value=code.data;scan();return}}frame=requestAnimationFrame(tick)};frame=requestAnimationFrame(tick)}catch{if(!disposed&&scope===epoch&&cameraScope===cameraEpoch){stopCamera();error.value='Camera unavailable. Allow camera access in system settings, or use a scanner or product search.'}}finally{openingCamera=false}}
onMounted(initialize)
onUnmounted(()=>{disposed=true;epoch++;controller.abort();searchRequest?.abort();stopCamera()})
defineExpose({leave})
</script>

<template>
  <section v-loading="loading" class="stock-panel">
    <div class="stock-heading"><div><h1>Stock movements</h1><p>Scan each item once, review the list and submit.</p></div><div><el-button :type="mode==='inbound'?'primary':'default'" :disabled="busy || !!pending" @click="changeKind('inbound')">Stock in</el-button><el-button :type="mode==='outbound'?'primary':'default'" :disabled="busy || !!pending" @click="changeKind('outbound')">Stock out</el-button></div></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false" /><el-alert v-if="notice" :title="notice" type="info" :closable="false" />
    <div v-if="pending" class="pending-request"><h2>Transaction awaiting verification</h2><p>{{ pending.kind==='outbound'?'Stock out':'Stock in' }} · {{ pending.requestId }}</p><p>Verify or retry this original request. Starting a new request could duplicate stock.</p><el-button :disabled="busy" @click="verify">Verify result</el-button><el-button :disabled="busy || obsolete" @click="retry">Retry original request</el-button><el-button v-if="obsolete && notFound" :disabled="busy" @click="discardObsolete">Discard obsolete request</el-button></div>
    <template v-else>
      <div class="stock-entry-grid"><div class="stock-scan-box"><h2>{{ kind==='inbound'?'Stock in':'Stock out' }}</h2><form @submit.prevent="scan"><label for="movement-scan">Product QR</label><el-input id="movement-scan" ref="scanInput" v-model="token" aria-label="Product QR" autocomplete="off" autocapitalize="off" :spellcheck="false" maxlength="128" :disabled="busy || storageFailed" /><p>Keep focus here. Use an Enter suffix on the scanner.</p><el-button native-type="submit" :disabled="busy || !token.trim()">Add scan</el-button><el-button :disabled="busy" @click="camera ? stopCamera() : startCamera()">{{ camera?'Stop camera':'Start camera' }}</el-button><span v-if="scanCount">Reading scan…</span></form><video v-if="camera" ref="video" playsinline muted class="scan-video" /></div><div class="stock-search-box"><h2>Find a product</h2><form @submit.prevent="search(false)"><el-input v-model="query" aria-label="Search product name or code" placeholder="Product name or code" maxlength="128" /><el-button native-type="submit" :disabled="searching">Search products</el-button></form><div class="stock-search-results"><div v-for="row in matches" :key="row.id"><span>{{ row.name }}<small>{{ row.productCode }}</small></span><el-button :disabled="busy" :aria-label="'Add '+row.productCode" @click="add(row)">Add 1</el-button></div></div><el-button v-if="cursor" :disabled="searching" @click="search(true)">More search results</el-button></div></div>
      <div class="stock-list-heading"><h2>Review list</h2><span>{{ items.length }} {{ items.length===1?'product':'products' }} · {{ total }} {{ total==='1'?'item':'items' }}</span></div><el-table :data="items" empty-text="Scan or search for a product to begin" class="movement-items"><el-table-column prop="name" label="Product" min-width="180" /><el-table-column prop="productCode" label="Code" min-width="130" /><el-table-column label="Quantity" min-width="160"><template #default="{row}"><el-button :disabled="busy" :aria-label="'Decrease '+row.productCode" @click="adjust(row,-1)">−</el-button><strong class="movement-quantity">{{ row.quantity }}</strong><el-button :disabled="busy" :aria-label="'Increase '+row.productCode" @click="adjust(row,1)">+</el-button></template></el-table-column><el-table-column label="Actions" width="110"><template #default="{row}"><el-button :disabled="busy" @click="items=items.filter(item=>item!==row)">Remove</el-button></template></el-table-column></el-table>
      <div class="stock-actions"><el-button type="primary" :disabled="busy || !!scanCount || !items.length || storageFailed" :loading="busy" @click="submit">Submit stock</el-button><el-button :disabled="busy || !!scanCount || !items.length" @click="saveDraft">Save draft</el-button><el-button :disabled="busy || !!scanCount" @click="reloadDraft">Refresh draft</el-button><el-button v-if="draft" :disabled="busy" @click="loadDraft">Load draft</el-button><el-button v-if="draft" :disabled="busy" @click="discardDraft">Discard draft</el-button><span v-if="draft">Saved {{ draft.kind==='inbound'?'stock-in':'stock-out' }} draft</span></div>
    </template>
    <div v-if="result" class="stock-result"><h2>{{ result.kind==='outbound'?'Stock-out':'Stock-in' }} committed quantities</h2><p v-for="row in result.items" :key="row.productId">{{ row.name }} · {{ row.productCode }} · Changed {{ result.kind==='outbound'?'-':'+' }}{{ row.quantity }} · Stock after {{ row.afterQuantity }}</p></div>
  </section>
</template>

<style scoped>
.stock-heading { display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:26px; }.stock-heading p,.stock-scan-box p,.pending-request p,.stock-result p { color:#8290a6;font-size:13px;line-height:1.7; }.stock-entry-grid { display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-bottom:28px; }.stock-scan-box,.stock-search-box,.pending-request,.stock-result { border:1px solid #e6ebf3;border-radius:10px;padding:22px;background:#f8faff; }.stock-panel h2 { font-size:14px;font-weight:600;margin:0 0 18px; }.stock-scan-box label { display:block;font-size:12px;color:#74829a;margin-bottom:8px; }.stock-scan-box form>span { display:block;font-size:12px;color:#74829a;margin-top:14px; }.stock-search-box form { display:flex;gap:12px; }.stock-search-results { max-height:250px;overflow:auto;margin-top:16px; }.stock-search-results>div { display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 0;border-top:1px solid #e6ebf3;font-size:12px;color:#52637c; }.stock-search-results small { display:block;color:#99a4b5;margin-top:5px; }.stock-list-heading { display:flex;justify-content:space-between;gap:20px; }.stock-list-heading span,.stock-actions>span { font-size:12px;color:#8290a6; }.movement-quantity { display:inline-block;text-align:center;min-width:42px; }.stock-actions { display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-top:22px; }.stock-actions .el-button { margin:0; }.stock-result { margin-top:26px; }.pending-request { margin:20px 0; }.pending-request p { overflow-wrap:anywhere; }.scan-video { display:block;width:100%;max-height:300px;object-fit:contain;margin-top:18px;border-radius:8px; }
@media(max-width:950px) { .stock-entry-grid { grid-template-columns:1fr; }.stock-heading { align-items:flex-start;flex-direction:column; } }
</style>
